void process_hid_field(struct hid_device *hid, struct hid_field *field, __u8 *data, int interrupt)
{
    int i;
    __s32 *value = kmalloc(field->maxfield * sizeof(__s32), GFP_KERNEL);

    for (i = 0; i < field->maxusage; i++) {
        __s32 v = hid->ll_driver->report_raw_value ? hid->ll_driver->report_raw_value(hid, field, i, data) : 0;

        if (field->logical_minimum <= v && v <= field->logical_maximum) {
            value[i] = v;
            hid_process_event(hid, field->report_type, field, i, v);
        }
    }

    memcpy(field->value, value, field->maxfield * sizeof(__s32));
    kfree(value);
}

void hid_process_values(struct hid_device *hid, struct hid_field *field, __u8 *data, int interrupt)
{
	struct hid_value *value;
	int i;

	value = kzalloc(field->maxusage * sizeof(struct hid_value), GFP_KERNEL);
	if (!value)
		return;

	for (i = 0; i < field->maxusage; i++) {
		struct hid_usage *usage = &field->usage[i];
		int n = 0;

		if (!usage->hid)
			continue;

		if (field->logical_minimum > 0 && field->logical_maximum > 0) {
			n = hid_input_logical_value(field, usage, data, i);
		} else {
			n = hid_input_value(field, usage, data, i);
		}

		value[i].value = n;

		if (!field->nonlinear) {
			if (n <= field->logical_minimum ||
			    n >= field->logical_maximum)
				continue;

			if (usage->type == EV_KEY && n == 0)
				continue;

			hid_process_event(hid, usage->type, usage->code, n, interrupt);
		}
	}

	memcpy(field->value, value, field->maxusage * sizeof(struct hid_value));
	kfree(value);
}

void process_hid_field(struct hid_device *hid, struct hid_field *field, __u8 *data, int interrupt)
{
	struct hid_value *value;
	int i, j;
	int n = field->maxusage;

	value = kmalloc(n * sizeof(struct hid_value), GFP_KERNEL);
	if (!value)
		return;

	for (i = 0; i < field->report_count; i++) {
		for (j = 0; j < n; j++) {
			value[j].raw = hid_input_raw_field(hid, field, data + i * field->report_size, j);
			if (value[j].logical >= field->logical_minimum && value[j].logical <= field->logical_maximum) {
				hid_process_event(field->usage, value + j, interrupt);
			}
		}
	}

	for (j = 0; j < n; j++)
		field->value[j] = value[j];

	kfree(value);
}

void process_hid_input(struct hid_device *hid, struct hid_field *field, __u8 *data, int interrupt)
{
    __s32 *value = kmalloc(field->maxusage * sizeof(__s32), GFP_KERNEL);
    if (!value)
        return;

    int i;
    for (i = 0; i < field->maxusage; i++) {
        hid_input_data(field, data, 0, 0);
        __s32 val = hid_get_val(field, i);

        if (val >= field->logical_minimum && val <= field->logical_maximum) {
            hid_process_event(hid, field->usage->hid, val, interrupt);
        }
    }

    for (i = 0; i < field->maxusage; i++) {
        field->value[i] = value[i];
    }

    kfree(value);
}

void process_hid_input(struct hid_device *hid, struct hid_field *field, __u8 *data, int interrupt)
{
    int i;
    struct hid_value *values = kmalloc(field->maxusage * sizeof(struct hid_value), GFP_KERNEL);

    for (i = 0; i < field->maxusage; i++) {
        struct hid_value *value = &field->value[i];
        __s32 l = hid->ll_driver->hidinput_input_event(hid, field, i, value->raw_value, 0);

        if (l < field->logical_minimum || l > field->logical_maximum)
            continue;

        if (hid_process_event(hid, field->hidinput, i, l))
            continue;

        value->value = l;
    }

    for (i = 0; i < field->maxusage; i++)
        field->value[i].raw_value = field->value[i].value;

    kfree(values);
}
